INSERT INTO `assets_sites` VALUES (28,1,'Etiam Egestas Risus Amet'),(41,1,NULL),(42,1,NULL),(43,1,NULL),(470,1,'Craft control panel showing a Matrix field with reusable page blocks.'),(487,1,'Craft control panel showing reusable components embedded in a CKEditor rich-text field.'),(700,1,''),(878,1,NULL),(925,1,'Wooden letter tiles spelling “In the beginning” on a white background.'),(972,1,NULL),(1014,1,NULL),(1111,1,NULL),(1123,1,'A person sketching interface ideas on paper at a desk with markers and a smartphone.'),(1196,1,NULL),(1494,1,NULL),(1688,1,NULL),(1804,1,'Wooden letter tiles spelling “Keep things simple” on a white background.'),(1821,1,'A softly lit workspace with a monitor displaying “Do what is great”.'),(1836,1,NULL),(2084,1,NULL),(2267,1,'Craft Kit demo site scoring 100 in Performance, Accessibility, Best Practices and SEO on Google Lighthouse.'),(2292,1,'LLM Ready Plugin showing Markdown output for a Craft CMS entry — appending .md to any URL returns clean, machine-readable content.'),(2434,1,NULL),(2525,1,'A tactile architectural model of orange, ivory and graphite blocks arranged as a modular page.'),(2526,1,'An open ivory folio with paragraph-like grooves and inset orange and graphite components.'),(2527,1,'Four upright ivory, orange and graphite card-like blocks arranged on a low plinth.'),(2528,1,'A folded ivory accordion sculpture with an orange central panel and graphite end supports.'),(2679,1,'Three ivory and orange modular blocks beside an open folio with paragraph-like grooves and an orange inset.'),(2680,1,'An exploded architectural pavilion with an orange structural core, hovering ivory roof and graphite plan slab.'),(2681,1,'An ivory miniature pavilion on a graphite foundation, with an orange doorway keystone and spare building blocks.'),(2682,1,'Two miniature buildings: an open graphite frame with orange modules and an ivory facade with an orange doorway.'),(2683,1,'An orange folded ribbon directly connects two ivory planes beside three separate graphite frames.'),(2684,1,'An orange channel runs up three ivory tiers between orderly rows of graphite and ivory document-like slabs.'),(2685,1,'A blank orange circular token within a mesh of ivory and graphite nodes connected by slender rods.'),(2686,1,'Ivory architectural panels joined by an orange dovetail in a graphite frame, beside simple drafting tools.'),(2687,1,'An open ivory folio on a graphite plinth, with orange and ivory material strips held by a fine alignment guide.'),(2688,1,'One orange conduit passes through three ivory panels beside two separate channels joined by small bridges.'),(2689,1,'An architectural campus of small ivory and graphite buildings linked to an orange spine on one shared base.'),(2690,1,'Three joined ivory bridge arches carry an orange walkway across a gap in a graphite plinth.'),(2691,1,'Ivory document sheets pass through a graphite frame into three separated panels connected by orange ribbons.'),(2692,1,'An ivory module with an orange inset slides along matching guides into a larger graphite architectural framework.'),(2829,1,'Three ivory modules with an open shutter, a recessed panel and sliding slabs, linked by an orange ribbon on one graphite base.');
